export class INFECTDictionaryUtils {
  static findByCode(code: string): MedicalCodeEntry | undefined {
    return INFECT_ICD10_DATABASE.find(item => item.code.toLowerCase() === code.toLowerCase());
  }

  static searchByDescription(query: string): MedicalCodeEntry[] {
    const q = query.toLowerCase();
    return INFECT_ICD10_DATABASE.filter(item => item.description.toLowerCase().includes(q));
  }
}
